#!/usr/bin/env bash
set -e

# Auto-detect project directory if not currently inside it
if [ ! -f "server.ts" ] && [ ! -f "package.json" ]; then
  echo "--> در حال پیدا کردن پوشه پروژه روی سرور..."
  TARGET_DIR=$(pwdx $(pgrep -f "server.ts" | head -n1) 2>/dev/null | awk '{print $2}')
  if [ -z "$TARGET_DIR" ] || [ ! -f "$TARGET_DIR/server.ts" ]; then
    TARGET_DIR=$(find / -maxdepth 4 -name "server.ts" -not -path "*/node_modules/*" 2>/dev/null | head -n1 | xargs dirname)
  fi
  if [ -n "$TARGET_DIR" ] && [ -d "$TARGET_DIR" ]; then
    echo "--> ورود به پوشه پروژه: $TARGET_DIR"
    cd "$TARGET_DIR"
  else
    echo "خطا: پوشه پروژه پیدا نشد! لطفا ابتدا با دستور cd وارد پوشه پروژه شوید."
    exit 1
  fi
fi

echo '=== شروع به‌روزرسانی نهایی و قطعی DocuShift روی سرور ==='

# ۰. فچ آخرین تغییرات از گیت‌هاب در صورت وجود
git pull 2>/dev/null || true

# ۱. دانلود فونت استاندارد وزیرمتن
echo '۱. به‌روزرسانی فونت Vazirmatn...'
mkdir -p server/assets/fonts
curl -sL https://raw.githubusercontent.com/rastikerdar/vazirmatn/master/fonts/ttf/Vazirmatn-Regular.ttf -o server/assets/fonts/persian-font.ttf || true

# ۲. به‌روزرسانی موتور حروف فارسی
echo '۲. به‌روزرسانی موتور حروف فارسی...'
cat << 'PERS' > server/processors/persianShaper.ts
export function sanitizePersianSymbols(raw: string): string {
  if (!raw) return '';
  return raw
    .replace(/[\uFEFF\u200B\u200E\u200F]/g, '')
    .replace(/[«»“”]/g, '"')
    .replace(/[‘’]/g, "'")
    .replace(/[••●■▪◦∙]/g, '-')
    .replace(/[—–]/g, '-')
    .replace(/\|/g, ' - ')
    .replace(/[⚠️⚠]/g, '[!]');
}

export function prepareRtlText(text: string): string {
  if (!text) return '';
  let clean = sanitizePersianSymbols(text);

  // Reverse Latin words so fontkit's RTL layout engine renders them in correct LTR direction
  clean = clean.replace(/[a-zA-Z0-9]+(?:[\.\-_/][a-zA-Z0-9]+)*/g, (match) => {
    return match.split('').reverse().join('');
  });

  return clean;
}

export interface BidiSegment {
  text: string;
  isRtl: boolean;
}

export function segmentBidiText(line: string): BidiSegment[] {
  if (!line) return [];
  const clean = sanitizePersianSymbols(line);
  const regex = /[؀-ۿݐ-ݿࢠ-ࣿﭐ-﷿ﹰ-﻿‌]+|[^؀-ۿݐ-ݿࢠ-ࣿﭐ-﷿ﹰ-﻿‌]+/g;
  const matches = clean.match(regex) || [];
  
  return matches.map((token) => ({
    text: token,
    isRtl: /[؀-ۿݐ-ݿࢠ-ࣿﭐ-﷿ﹰ-﻿]/.test(token),
  }));
}

PERS

# ۳. استقرار اعتبارسنج سبک و رفع هنگی مرحله صحت‌سنجی
echo '۳. استقرار اعتبارسنج پرسرعت و بدون هنگی...'
base64 -d << 'VALB64' > server/validation/documentValidator.ts

VALB64

# ۴. استقرار قطعی پردازنده PDF
echo '۴. استقرار پردازنده PDF...'
base64 -d << 'PDFB64' > server/processors/pdfProcessor.ts

PDFB64

# ۵. کامپایل نهایی و ری‌استارت
echo '۵. بیلد مجدد و ری‌استارت PM2...'
npm run build
pm2 restart docushift || true

echo '=== به‌روزرسانی با موفقیت کامل به پایان رسید! ==='
